def design(z, s, c=None, centers=None):
    st = np.asarray(s)[:, None] == [1, 2]
    parts = [z, st.astype(float)]
    if c is not None:
        parts.append(5 * ((np.asarray(c)[:, None] == centers) - 1 / len(centers)))
    return np.column_stack(parts)

def score(y, p):
    from sklearn.metrics import balanced_accuracy_score
    from sklearn.metrics import brier_score_loss
    from sklearn.metrics import roc_auc_score
    return np.array([roc_auc_score(y, p), brier_score_loss(y, p), balanced_accuracy_score(y, p >= 0.5)])
